import{_ as s,o as a,c as t,a5 as d}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"휠 제어 — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/wheel.md","filePath":"ko/software/sdk/cpp/wheel.md","lastUpdated":1793350928000}'),i={name:"ko/software/sdk/cpp/wheel.md"};function o(n,e,l,p,r,c){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="휠-제어-—-c-예제" tabindex="-1">휠 제어 — C++ 예제 <a class="header-anchor" href="#휠-제어-—-c-예제" aria-label="Permalink to &quot;휠 제어 — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq/rbq_wheel.cpp</code></p><p>외부 앱에서 **RBQ 휠 기체(RBQ-W)**의 바퀴 네 개를 돌립니다. 바퀴 관절의 소유권만 가져오므로 다리는 로봇의 제어기가 계속 맡고 서 있는 자세도 유지됩니다. 몇 초 동안 바퀴를 굴린 뒤 놓아 줍니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><ol><li>명령행에서 <code>interface</code>와 선택 인자 <code>torque kd seconds</code>를 읽습니다.</li><li>주어진 인터페이스로 DDS <code>ChannelFactory</code>를 초기화하고 <strong>앱 슬롯 21</strong> 용으로 <code>rt/rbq/ref/motion/_21</code>의 <code>Publisher&lt;MotionRef_&gt;</code>와 <code>rt/rbq/cmd/motion/owner/_21</code>의 <code>Publisher&lt;JointOwnershipCmd_&gt;</code>를 만듭니다. 로봇이 실제로 적용하는 레퍼런스인 <code>rt/rbq/ref/motion/_0</code>도 구독합니다.</li><li>DDS 디스커버리를 ~500 ms 기다린 뒤 토크 0 레퍼런스를 먼저 보내고, <code>whl_joint[] = true</code>인 <code>JointOwnershipCmd_</code>를 보냅니다(<code>leg_joint[]</code>는 <code>false</code> 그대로).</li><li><code>whl_joint[]</code>를 500 Hz 로 발행합니다 — <code>kp = 0</code>, 주어진 <code>kd</code>, 0.5 초 동안 0 에서 올라가는 토크. 0.5 초마다 적용된 바퀴 레퍼런스를 출력합니다.</li><li>시간이 끝나면 토크를 0 으로 0.5 초 보낸 뒤 <code>kp = kd = torque = 0</code>을 보내고 종료합니다.</li></ol><p><code>kp = 0</code>이면 바퀴 보드가 <code>torque − kd × 속도</code>를 내므로, 떠 있는 바퀴는 <strong>속도 = torque / kd</strong> [rad/s]에 수렴합니다. 기본값이면 2 rad/s 입니다.</p><p>게인은 CAN FD 기체든 일반 CAN 기체든 <strong>물리값</strong>(Nm/rad, Nm·s/rad)으로 보냅니다. 로봇의 <strong>Network</strong> 가 보드에 맞게 바꾸므로, 일반 CAN 기체에서는 보드 게인 단위로 반올림됩니다(예: kd 0.5 → 0.5007).</p><p><code>rbq_low_level</code>은 앱 슬롯 20 을 쓰므로 두 예제를 함께 돌릴 수 있습니다 — 다리는 한 앱이, 바퀴는 다른 앱이 맡습니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>바닥에 있으면 바퀴가 도는 동안 로봇이 <strong>굴러갑니다</strong>. 공간을 확보하고, 작은 토크부터 시작하고, 원격 비상정지를 손에 두세요.</p></div><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드·설치 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>로봇 스택이 실행 중이며 동일 DDS 인터페이스로 접근 가능.</li><li><strong>서 있는 RBQ 휠 기체(RBQ-W).</strong> 바퀴가 없는 기체에서는 명령이 아무 효과가 없습니다. 시뮬레이터에서는 Motion 과 MuJoCo 를 <code>--wheel</code>로 띄웁니다(<code>bash scripts/sim.bash --robot wheel</code>).</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리: <code>bin/rbq_wheel</code></p><h2 id="run" tabindex="-1">실행 <a class="header-anchor" href="#run" aria-label="Permalink to &quot;실행 {#run}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_wheel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [interface] [torque] [kd] [seconds]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 앞으로 2 rad/s, 3 초(기본값) — 인터페이스가 항상 먼저 옵니다:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_wheel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 뒤로 1 rad/s, 5 초:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_wheel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>인자는 모두 위치 인자이므로 <strong>인터페이스를 첫 인자로 넘겨야 합니다</strong>. 로봇에 닿는 인터페이스를 쓰세요 — 로봇 PC 에서 돌리면 <code>lo</code>, 다른 호스트에서는 본인 NIC.</p><table tabindex="0"><thead><tr><th>인자</th><th>의미</th><th>기본값</th></tr></thead><tbody><tr><td><code>interface</code></td><td>CycloneDDS 인터페이스(로봇에서는 <code>lo</code> / 다른 호스트에서는 NIC)</td><td>—</td></tr><tr><td><code>torque</code></td><td>바퀴 피드포워드 토크 [Nm], |torque| ≤ 10</td><td><code>1.0</code></td></tr><tr><td><code>kd</code></td><td>바퀴 감쇠 [Nm·s/rad], 0 &lt; kd ≤ 6</td><td><code>0.5</code></td></tr><tr><td><code>seconds</code></td><td>바퀴를 놓기 전까지 굴리는 시간</td><td><code>3</code></td></tr></tbody></table><p>범위를 벗어나면 사용법을 출력하고 아무것도 보내지 않은 채 종료합니다.</p><p>예제가 끝난 뒤에도 바퀴는 게인 0 인 채로 앱 21 소유로 남아 자유롭게 돕니다. 다시 서기나 보행 전환을 해도 로봇에게 돌아가지 않습니다. 로봇의 제어기가 바퀴를 다시 써야 하면 로봇 스택을 재시작하세요.</p><h2 id="출력-예시" tabindex="-1">출력 예시 <a class="header-anchor" href="#출력-예시" aria-label="Permalink to &quot;출력 예시&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_wheel] wheel ownership requested (app 21)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=0 kd=3.5) HLW(tq=0 kd=3.5) FRW(tq=0 kd=3.5) FLW(tq=0 kd=3.5)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=0.996 kd=0.5) HLW(tq=0.996 kd=0.5) FRW(tq=0.996 kd=0.5) FLW(tq=0.996 kd=0.5)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=1 kd=0.5) HLW(tq=1 kd=0.5) FRW(tq=1 kd=0.5) FLW(tq=1 kd=0.5)</span></span>
<span class="line"><span>[rbq_wheel] done - wheels released (kp = kd = torque = 0)</span></span></code></pre></div><p>첫 줄은 넘겨받기 전 로봇 자신의 바퀴 게인입니다. 바퀴 순서는 <code>HRW HLW FRW FLW</code>(관절 12–15)입니다.</p>`,24)])])}const b=s(i,[["render",o]]);export{k as __pageData,b as default};
